import pandas as pd
from pandas import Interval, IntervalArray

# Example 1: pd.Interval(0, 1, 'both').overlaps(pd.Interval(0, 0, 'right'))
try:
    result = pd.Interval(0, 1, 'both').overlaps(pd.Interval(0, 0, 'right'))
    probe("pd.Interval(0, 1, 'both').overlaps(pd.Interval(0, 0, 'right'))", result)
except Exception as e:
    probe("pd.Interval(0, 1, 'both').overlaps(pd.Interval(0, 0, 'right'))", "__error__: " + type(e).__name__ + ": " + str(e))

